{
  "name": "蓝牙音频链路控制器",
  "name_en": "Bluetooth Audio Link Controller",
  "manufacturer": "Yoctopuce",
  "description": "用于配置和控制 Yoctopuce 蓝牙音频链路的硬件功能，可设置配对 PIN、远端设备地址、静音、前置放大量和耳机音量，并执行连接、断开及链路状态管理。适合在实验系统中接入和管理蓝牙音频设备或无线音频链路。",
  "description_en": "A Yoctopuce hardware function for configuring and controlling a Bluetooth audio link. It can set the pairing PIN, remote device address, mute state, pre-amplifier level, and headset volume, and supports connect, disconnect, and link-state management. It is suitable for integrating and managing Bluetooth audio devices or wireless audio links in lab setups.",
  "tag_hints": [
    "Bluetooth audio link",
    "wireless audio control",
    "pairing PIN",
    "headset volume control",
    "audio preamplifier",
    "Bluetooth connection management",
    "signal strength monitoring"
  ],
  "actions": [
    {
      "action_name": "auto-set_pairingPin",
      "description": "设置蓝牙配对 PIN 码",
      "description_en": "set the Bluetooth pairing PIN"
    },
    {
      "action_name": "auto-set_remoteAddress",
      "description": "设置远端蓝牙设备 MAC-48 地址",
      "description_en": "set the remote Bluetooth device MAC-48 address"
    },
    {
      "action_name": "auto-set_mute",
      "description": "设置静音状态",
      "description_en": "set the mute state"
    },
    {
      "action_name": "auto-set_preAmplifier",
      "description": "设置音频前置放大量",
      "description_en": "set the audio pre-amplifier volume"
    },
    {
      "action_name": "auto-set_volume",
      "description": "设置已连接耳机音量",
      "description_en": "set the connected headset volume"
    },
    {
      "action_name": "auto-set_command",
      "description": "设置命令字符串",
      "description_en": "set the command string"
    },
    {
      "action_name": "auto-connect",
      "description": "连接到已选择的远端蓝牙设备",
      "description_en": "connect to the selected remote Bluetooth device"
    },
    {
      "action_name": "auto-disconnect",
      "description": "断开与已选择远端蓝牙设备的连接",
      "description_en": "disconnect from the selected remote Bluetooth device"
    },
    {
      "action_name": "auto-nextBluetoothLink",
      "description": "枚举下一个可访问的蓝牙音频链路控制器",
      "description_en": "enumerate the next accessible Bluetooth audio link controller"
    }
  ]
}

